package com.exe201.rrms.controller;
import com.exe201.rrms.entity.*;import com.exe201.rrms.repository.*;import com.exe201.rrms.service.*;import jakarta.servlet.http.HttpServletRequest;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/payments") public class PaymentController {private final AuthService auth;private final PaymentService pay;private final PaymentRepository payments;private final WalletTransactionRepository txs;private final PackagePlanRepository plans;@Value("${unihome.payment.demo:true}")boolean demo;public PaymentController(AuthService a,PaymentService p,PaymentRepository pr,WalletTransactionRepository t,PackagePlanRepository pl){auth=a;pay=p;payments=pr;txs=t;plans=pl;} @GetMapping("/wallet") public Map<String,Object>wallet(HttpServletRequest r){Long id=auth.current(r).getId();return Map.of("balance",pay.balance(id),"transactions",txs.findByUserIdOrderByCreatedAtDesc(id));} @GetMapping("/plans") public List<PackagePlan>plans(){return plans.findByActiveTrueOrderByPriorityAsc();} @PostMapping("/topup") public Payment topup(HttpServletRequest r,@RequestBody Map<String,Object>b){return pay.createQr(auth.current(r).getId(),Long.parseLong(b.get("amount").toString()),"WALLET_TOPUP","WALLET",0L);} @PostMapping("/listing/{listingId}/direct") public Payment direct(@PathVariable Long listingId,HttpServletRequest r,@RequestBody Map<String,Object>b){PackagePlan p=plans.findById(Long.valueOf(b.get("planId").toString())).orElseThrow();Payment x=pay.createQr(auth.current(r).getId(),p.getPrice(),"PACKAGE_DIRECT","LISTING",listingId);x.setPlanId(p.getId());return payments.save(x);} @PostMapping("/listing/{listingId}/wallet") public Map<String,Object>walletBuy(@PathVariable Long listingId,HttpServletRequest r,@RequestBody Map<String,Object>b){pay.buyWithWallet(auth.current(r).getId(),listingId,Long.valueOf(b.get("planId").toString()));return Map.of("message","Đã kích hoạt gói");} @GetMapping("/history") public List<Payment> history(HttpServletRequest r){return payments.findByUserIdOrderByCreatedAtDesc(auth.current(r).getId());} @PostMapping("/{id}/demo-paid") public Map<String,Object>demoPaid(@PathVariable Long id){if(!demo)throw new SecurityException("Demo payment bị tắt");Payment p=payments.findById(id).orElseThrow();pay.markPaid(p);return Map.of("message","Đã xác nhận thanh toán demo");} }
